previewCss:
.darma-loader-darma-b12-city-skyline { --accent: var(--loader-color, #1e40af); --accent-2: var(--loader-secondary-color, #7c3aed); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .62); display: flex; align-items: flex-end; gap: 3%; }
.darma-loader-darma-b12-city-skyline span { position: relative; flex: 1; border-radius: 3px 3px 0 0; background: linear-gradient(var(--accent), var(--accent-2)); }
.darma-loader-darma-b12-city-skyline span::after { content: ''; position: absolute; inset: 14% 16% 8%; background: repeating-linear-gradient(to bottom, color-mix(in srgb, #fff 82%, transparent) 0 8%, transparent 8% 22%); -webkit-mask: repeating-linear-gradient(to right, #000 0 34%, transparent 34% 68%); mask: repeating-linear-gradient(to right, #000 0 34%, transparent 34% 68%); animation: darma-loader-darma-b12-city-skyline-windows calc(var(--loader-speed, 1s) * 1.6) steps(2, end) infinite; }
.darma-loader-darma-b12-city-skyline span:nth-child(1) { height: 54%; }
.darma-loader-darma-b12-city-skyline span:nth-child(2) { height: 80%; }
.darma-loader-darma-b12-city-skyline span:nth-child(3) { height: 100%; }
.darma-loader-darma-b12-city-skyline span:nth-child(4) { height: 66%; }
.darma-loader-darma-b12-city-skyline span:nth-child(5) { height: 88%; }
.darma-loader-darma-b12-city-skyline span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b12-city-skyline span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b12-city-skyline span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b12-city-skyline span:nth-child(5)::after { animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
@keyframes darma-loader-darma-b12-city-skyline-windows { 0% { opacity: .28; } 50% { opacity: 1; } 100% { opacity: .28; } }

